            // Perfect fit is always excellent
            score -= 10.0;
        }
    }

    // 3. Global state awareness: If we are near the end of the stream, 
    // be more aggressive about filling existing bins to avoid opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 0.5;
    }

    // 4. New Bin Logic: Discourage opening a new bin unless the current 
    // fitting options are extremely poor (i.e., leaving a very awkward residual).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 35.0;
        // If we have many open bins that could have taken this, punish starting a new one
        score += (fitting_bins_count as f64) * 15.0;
