    // If this is the only bin that fits the item, heavily incentivize it
    // to avoid opening a new bin unnecessarily.
    let fit_urgency = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -5000.0
    } else {
        0.0
    };

    // New bin penalty: If we are considering a new bin (bin_residual == bin_capacity),
    // apply a high cost to force usage of existing bins unless they are truly terrible.
    let new_bin_penalty = if bin_residual == bin_capacity {
        250.0 + (progress * 100.0)
    } else {
