    // Combine: Minimize the combined score.
    // frag_penalty discourages "bad" fits, lookahead_alignment encourages "optimal" future fits,
    // fit_urgency prevents unnecessary bin creation.
    let score = frag_penalty + (lookahead_alignment * 2.5) + fit_urgency + new_bin_penalty;

    score
